  if (fresh || !existsSync(OVERRIDE_CACHE)) return {components: {}, hooks: {}}
  try {
    const cache = JSON.parse(readFileSync(OVERRIDE_CACHE, 'utf-8'))
    return {components: cache.components ?? {}, hooks: cache.hooks ?? {}}
  } catch {
    return {components: {}, hooks: {}}
  }
}

function saveOverrideCache(cache) {
  writeFileSync(OVERRIDE_CACHE, JSON.stringify(cache, null, 2))
}

